package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for RandomStringUtils.randomAscii(int count)
 */
public class RandomStringUtils_randomAscii_TriageGen0Test {

    @Test
    public void testRandomAscii_PositiveCount() {
        int count = 10;
        String result = RandomStringUtils.randomAscii(count);

        assertNotNull("Result should not be null", result);
        assertEquals("Result length should match the requested count", count, result.length());

        // Verify all characters are within the ASCII printable range [32, 127)
        // Note: The implementation uses random(count, 32, 127, false, false)
        // which typically means characters from ASCII 32 up to (but not including) 127
        for (int i = 0; i < result.length(); i++) {
            char c = result.charAt(i);
            assertTrue("Character '" + c + "' should be >= 32", c >= 32);
            assertTrue("Character '" + c + "' should be < 127", c < 127);
        }
    }








}

