package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for RandomStringUtils.randomAscii(int count)
 */
public class RandomStringUtils_randomAscii_TriageGen0Test {









    @Test
    public void testRandomAscii_Consistency() {
        // Ensure that multiple calls produce different results (probabilistic test)
        int count = 20;
        String result1 = RandomStringUtils.randomAscii(count);
        String result2 = RandomStringUtils.randomAscii(count);

        // While there is a microscopic chance they are the same, 
        // for a length of 20 ASCII chars, they should be different.
        assertNotEquals("Successive calls should produce different strings", result1, result2);
    }
}
